  '9irsyadyig': R`Mentega meleleh`,
  '1gdxtmibb0k': R`Memecahkan gelas`,
  'gbe9a9ctlx': R`Air mendidih`,
  'fw068cfu8j': R`Apakah ini perubahan fisika atau kimia? <i>⟦0⟧</i>`,
  'huyib0112o': R`Terbentuk zat baru, jadi ini perubahan <b>kimia</b>.`,
  '1a197xh36zo': R`Tidak terbentuk zat baru, jadi ini perubahan <b>fisika</b>.`,
  '162mmf8rb9a': R`Suatu zat meleleh pada ⟦0⟧ dan mendidih pada ⟦1⟧. Apa wujudnya pada ⟦2⟧?`,
  '2pd9kbf1m4': R`Di bawah titik leleh zat itu padat, di antara titik leleh dan titik didih cair, di atas titik didih gas. Pada ⟦0⟧ zat itu <b>⟦1⟧</b>.`,
