  '16nx2p921ed': R`Tinta (kiri) mengandung dua zat warna. Noda yang setinggi zat warna yang sudah diketahui adalah zat warna itu. Jarak diukur dari garis awal.`,
  'x2y2x6kwmv': R`<p><b>Faktor retensi</b> suatu noda adalah</p><p>$$R_f = \frac{\text{jarak tempuh zat}}{\text{jarak tempuh pelarut}}$$</p><p>Nilainya selalu antara 0 dan 1, dan untuk kertas serta pelarut tertentu setiap zat memiliki $R_f$ sendiri.</p>`,
