  '8fagwh8a00': R`Metode apa yang paling tepat untuk memisahkan <b>⟦0⟧</b>?`,
  '26ejhr2gpxe': R`Pada kromatogram kertas, batas pelarut bergerak ⟦0⟧ dari garis awal dan noda zat warna bergerak ⟦1⟧. Berapa nilai $R_f$ zat warna itu?`,
  '1o1edur7g2q': R`Suatu zat memiliki $R_f = ⟦0⟧$. Jika batas pelarut bergerak ⟦1⟧, berapa jauh zat itu bergerak?`,
