  '6u21huqg2c': R`Gelas kimia dan labu erlenmeyer untuk menampung dan mencampur cairan, tetapi takarannya kasar. Gelas ukur mengukur volume; pipet mengeluarkan satu volume yang tepat; buret mengeluarkan volume berapa pun dengan teliti (dipakai dalam titrasi).`,
