  '10jwa7snuda': R`Piktogram bahaya Globally Harmonized System (GHS), dipakai pada label bahan kimia di seluruh dunia, termasuk di Indonesia.`,
  '10njbbucnr0': R`<p><b>Bekerja dengan aman.</b> Pakailah kacamata pelindung dan jas lab; ikat rambut panjang. Jangan makan atau minum di laboratorium. Arahkan tabung reaksi menjauhi orang saat memanaskannya. Selalu tambahkan <b>asam ke dalam air</b>, perlahan-lahan, jangan air ke dalam asam. Gunakan lemari asam untuk gas beracun. Laporkan setiap tumpahan dan kerusakan, dan bilas bahan kimia yang mengenai kulit dengan banyak air.</p>`,
  'a3ctmxln3g': R`Tampilan dekat gelas ukur dengan dasar meniskus pada 24,6 mL`,
  '239v67336kz': R`Bacalah bagian bawah permukaan yang melengkung (meniskus) dengan mata sejajar dengannya. Di sini hasil bacaannya $24{,}6\,\mathrm{mL}$.`,
