  '1gwtxen9oi8': R`Nol di belakang setelah koma desimal dihitung`,
  '1hrjzb6k36': R`<p><b>Akurasi</b> adalah seberapa dekat hasil dengan nilai sebenarnya; <b>presisi</b> adalah seberapa dekat hasil-hasil pengulangan satu sama lain.</p><p>$$\text{persentase kesalahan} = \frac{|\text{terukur} - \text{sebenarnya}|}{\text{sebenarnya}} \times 100\%$$</p>`,
