  'vt1p1nzcb9': R`Atom karbon-12: 6 proton dan 6 neutron di inti, 6 elektron dalam dua kulit (2, 4)`,
  '1lxzzq80igg': R`Atom karbon-12: 6 proton, 6 neutron, dan 6 elektron (2 di kulit pertama, 4 di kulit kedua).`,
  'b4fhy1sxon': R`<p><b>Nomor atom</b> $Z$ = jumlah proton (menentukan jenis unsur). <b>Nomor massa</b> $A$ = proton + neutron. Jadi</p><p>$$\text{neutron} = A - Z.$$</p><p>Atom netral memiliki elektron sebanyak protonnya. Notasi nuklida menuliskan kedua bilangan itu: $$ {}^{A}_{Z}\mathrm{X} \qquad \text{mis. } {}^{23}_{11}\mathrm{Na}: 11 \text{ proton},\ 12 \text{ neutron},\ 11 \text{ elektron}.$$</p>`,
