  'ek11knou55': R`Spektrum massa klorin: massa 35 sebesar 75,8 persen dan massa 37 sebesar 24,2 persen`,
  '1hlb0e2q2xt': R`Spektrometer massa mengukur isotop-isotop klorin: ⟦0⟧% klorin-35 dan ⟦1⟧% klorin-37 (kelimpahan IUPAC).`,
  '15iki7gpyr7': R`<p><b>Massa atom relatif</b> $A_r$ adalah massa rata-rata tertimbang isotop-isotopnya, dibandingkan dengan $\frac{1}{12}$ massa atom karbon-12:</p><p>$$A_r = \frac{\sum (\text{massa} \times \text{kelimpahan})}{100} \qquad A_r(\mathrm{Cl}) = \frac{35 \times 75{,}8 + 37 \times 24{,}2}{100} = ⟦0⟧$$</p>`,
  'sfh80mjetv': R`<p>Nomor massa selalu bilangan bulat (menghitung partikel); massa atom relatif biasanya tidak, karena merupakan rata-rata dari isotop-isotopnya.</p>`,
  '2b4l8tgnmwl': R`Berapa jumlah ⟦0⟧ dalam atom netral $⟦1⟧$?`,
  'n535jxmjjw': R`elektron`,
  '1d4rcf6os8t': R`$Z = ⟦0⟧$ proton, $A - Z = ⟦1⟧ - ⟦2⟧ = ⟦3⟧$ neutron, dan ⟦4⟧ elektron dalam atom netral.`,
  '1zz9sarshhg': R`Berapa jumlah elektron ion $\ce{⟦0⟧^{⟦1⟧}}$? (nomor atom ⟦2⟧: ⟦3⟧)`,
  '2ez1zfe26ny': R`Ion ini melepas ⟦0⟧ elektron⟦1⟧: $⟦2⟧ - ⟦3⟧ = ⟦4⟧$.`,
  '17da2kqh9rj': R`Ion ini menerima ⟦0⟧ elektron⟦1⟧: $⟦2⟧ + ⟦3⟧ = ⟦4⟧$.`,
