  '1u9agguvo92': R`\Delta E = E_{\text{tinggi}} - E_{\text{rendah}} = h f = \frac{hc}{\lambda} \qquad \lambda\ (\mathrm{nm}) \approx \frac{1240}{\Delta E\ (\mathrm{eV})}`,
  '292o67civj5': R`Tingkat energi hidrogen dengan elektron yang turun dari tingkat 3, 4, dan 5 ke tingkat 2, serta dari 2 ke 1`,
  '2198n5cef72': R`Transisi ke $n = 2$ menghasilkan cahaya tampak (merah 656 nm, biru-hijau 486 nm, ungu 434 nm); transisi ke $n = 1$ menghasilkan ultraungu.`,
  '1ltiecer718': R`<p>Setiap unsur memiliki susunan tingkat energinya sendiri, sehingga <b>spektrum garisnya</b> bagaikan sidik jari. Memanaskan senyawa dalam nyala api menampakkan warna ion logamnya: natrium kuning, kalium ungu muda, litium merah, kalsium jingga-merah, stronsium merah tua, barium hijau, tembaga biru-hijau. Kembang api memanfaatkan warna-warna ini.</p>`,
  'h73mjls24v': R`<p>Elektron dalam model Bohr bukan planet kecil: dalam model modern kita hanya tahu di mana elektron <i>mungkin</i> berada, itulah sebabnya kita menyebut orbital, bukan orbit.</p>`,
  '1513g6s0f21': R`menemukan elektron dan mengusulkan model "roti kismis"`,
