  '24hikhm7f9h': R`Schrödinger`,
  '1e7zyawdh5b': R`Ilmuwan manakah yang ⟦0⟧?`,
  '1pvybszow9v': R`Dengan $E_n = -\frac{13{,}6}{n^2}$ eV, tentukan energi (dalam eV) foton yang dipancarkan ketika elektron hidrogen turun dari $n = ⟦0⟧$ ke $n = ⟦1⟧$.`,
  '201gmo3vzs8': R`$\Delta E = 13{,}6\left(\frac{1}{⟦0⟧^2} - \frac{1}{⟦1⟧^2}\right) = ⟦2⟧$ eV.`,
  's0rrcwliv8': R`Sebuah foton berenergi ⟦0⟧. Dengan $\lambda \approx \frac{1240}{\Delta E}$ nm, berapa panjang gelombangnya (dalam nm)?`,
