  '1uzxf3pio88': R`<p>Gas mulia hampir tidak bereaksi karena kulit terluarnya sudah penuh (8 elektron, atau 2 untuk helium). Atom lain dapat mencapai kulit terluar yang penuh, yaitu <b>oktet</b>, dengan melepas, menerima, atau memakai bersama elektron: inilah yang membuat atom-atom berikatan.</p>
<p>Atom logam dengan 1–3 elektron terluar mudah melepasnya; atom nonlogam dengan 5–7 elektron terluar mudah menerima elektron. Ketika keduanya bertemu, elektron <b>berpindah</b> dari logam ke nonlogam, dan ion-ion yang muatannya berlawanan saling tarik-menarik. Gaya tarik elektrostatik inilah yang disebut <b>ikatan ion</b>.</p>
⟦0⟧
⟦1⟧
<h3>Kisi ion</h3>
<p>Senyawa ion tidak membentuk molekul terpisah. Setiap ion dikelilingi ion-ion bermuatan berlawanan, berulang ke segala arah membentuk <b>kisi ion raksasa</b>. Rumusnya hanya menyatakan <i>perbandingan</i> ion.</p>
⟦2⟧
⟦3⟧
⟦4⟧
⟦5⟧`,
  '1dif3jhm5jc': R`Diagram titik-silang: natrium memberikan satu elektron terluarnya kepada klorin, membentuk ion Na plus dan Cl minus`,
  'sz4vnbqp78': R`Natrium (silang) memberikan satu-satunya elektron terluarnya kepada klorin (titik): $\ce{Na+}$ dan $\ce{Cl-}$ sama-sama memiliki kulit terluar yang penuh. (Hanya kulit terluar yang digambar.)`,
  'nfyb9gkqt': R`Magnesium memberikan satu elektron kepada masing-masing dari dua atom klorin, membentuk ion Mg dua plus dan dua ion Cl minus`,
  'nkzxju7xyq': R`Magnesium memiliki dua elektron terluar, jadi memerlukan dua atom klorin: $\ce{MgCl2}$.`,
  '26mj46o20f1': R`Sebagian kisi natrium klorida: ion natrium yang kecil dan ion klorida yang besar berselang-seling dalam kubus`,
  '1kv2ijg03id': R`Sebagian kisi natrium klorida: setiap $\ce{Na+}$ dikelilingi 6 $\ce{Cl-}$ dan setiap $\ce{Cl-}$ dikelilingi 6 $\ce{Na+}$.`,
  'lzi8oq05x9': R`<p><b>Menulis rumus:</b> jumlah muatan positif harus sama dengan jumlah muatan negatif. Tukar silang angka muatannya (aturan "silang") lalu sederhanakan: $\ce{Al^3+}$ dan $\ce{O^2-}$ menjadi $\ce{Al2O3}$; $\ce{Ca^2+}$ dan $\ce{NO3-}$ menjadi $\ce{Ca(NO3)2}$ (ion poliatom yang diambil lebih dari satu diberi kurung).</p><p><b>Tata nama:</b> logam lebih dahulu, lalu nonlogam dengan akhiran <i>-ida</i>: natrium klorida, magnesium oksida. Ion yang mengandung oksigen memiliki nama sendiri: sulfat $\ce{SO4^2-}$, nitrat $\ce{NO3-}$, karbonat $\ce{CO3^2-}$, hidroksida $\ce{OH-}$, fosfat $\ce{PO4^3-}$, amonium $\ce{NH4+}$.</p>`,
  '1tnnx5q7iwg': R`Sifat senyawa ion`,
  '27uz1w1s5y2': R`Alasan`,
  '1a1lxmjgcyg': R`titik leleh dan titik didih tinggi`,
  'bub994r6ys': R`banyak gaya tarik kuat antarion yang harus diatasi`,
  '1lupx84ga17': R`menghantarkan listrik saat meleleh atau larut, tidak saat padat`,
