  '286ie9rb4lx': R`pergeseran kisi mendekatkan muatan sejenis yang saling tolak`,
  '111kt4uv5rm': R`<p>Logam transisi dapat membentuk lebih dari satu jenis ion; muatannya ditulis dengan angka Romawi: besi(II) klorida $\ce{FeCl2}$, besi(III) klorida $\ce{FeCl3}$.</p>`,
  'd0sxfq8o77': R`Apa rumus senyawa dari $\ce{⟦0⟧⟦1⟧}$ dan $\ce{⟦2⟧⟦3⟧}$?`,
  '10znzbwllue': R`Setarakan muatannya: $⟦0⟧ \times (+⟦1⟧) = ⟦2⟧ \times (−⟦3⟧)$, jadi $\ce{⟦4⟧}$.`,
