  '1g8erltbi4u': R`Kisi raksasa menahan ikatan ion yang kuat ke segala arah.`,
  '1w9jjwixf5g': R`<p>Dua atom nonlogam sama-sama ingin menerima elektron, jadi tidak ada yang mau melepas. Sebagai gantinya, keduanya <b>memakai bersama</b> sepasang elektron, satu dari masing-masing atom. Pasangan elektron bersama ini adalah <b>ikatan kovalen</b>; ia mengikat kedua inti karena keduanya menarik elektron bersama itu.</p>
⟦0⟧
⟦1⟧
<h3>Struktur Lewis</h3>
<p><b>Struktur Lewis</b> menggambarkan setiap pasangan elektron ikatan sebagai garis dan setiap pasangan elektron bebas sebagai dua titik. Cara menggambarnya: (1) jumlahkan semua elektron valensi, (2) hubungkan atom-atom dengan ikatan tunggal (atom yang paling kurang elektronegatif biasanya di tengah, hidrogen selalu di tepi), (3) lengkapi oktet atom-atom luar dengan pasangan elektron bebas, (4) letakkan sisa elektron pada atom pusat, dan (5) jika atom pusat belum oktet, ubah pasangan elektron bebas menjadi ikatan rangkap dua atau tiga.</p>
⟦2⟧
⟦3⟧
<h3>Kepolaran ikatan</h3>
<p><b>Keelektronegatifan</b> adalah kemampuan atom menarik elektron ikatan. Jika dua atom berbeda memakai bersama elektron, atom yang lebih elektronegatif menariknya lebih dekat dan mendapat muatan parsial negatif $\delta-$, atom lainnya $\delta+$: ikatannya <b>polar</b>.</p>
⟦4⟧
⟦5⟧`,
