  '1jv11xiilv6': R`<p>Satu pasangan elektron bersama adalah <b>ikatan tunggal</b> (C–H), dua pasangan <b>ikatan rangkap dua</b> (O=C=O), tiga pasangan <b>ikatan rangkap tiga</b> (N≡N). Pasangan elektron terluar yang tidak dipakai bersama disebut <b>pasangan elektron bebas</b>. Makin banyak pasangan bersama, makin pendek dan kuat ikatannya.</p>`,
