  'xfpwu2g6rp': R`<p>Pada <b>ikatan kovalen koordinasi</b>, kedua elektron bersama berasal dari atom yang sama. Contoh: $\ce{NH3 + H+ -> NH4+}$: pasangan elektron bebas nitrogen berikatan dengan $\ce{H+}$. Setelah terbentuk, ikatan ini sama persis dengan ikatan N–H lainnya.</p>`,
