  '1zpsy3a2ljt': R`<p>Molekul bersifat <b>polar</b> jika memiliki ikatan polar <i>dan</i> ikatan-ikatan itu tidak saling meniadakan. Pada $\ce{CO2}$ kedua dipol C=O berlawanan arah dan saling meniadakan: $\ce{CO2}$ nonpolar. Pada $\ce{H2O}$ bentuknya bengkok sehingga dipolnya saling menjumlah: air bersifat polar. Bentuk simetris dengan atom-atom luar yang sama ($\ce{CH4}$, $\ce{BF3}$, $\ce{CCl4}$, $\ce{SF6}$) bersifat nonpolar.</p>`,
  'csuy5fotqn': R`Karbon dioksida: kedua dipol saling meniadakan`,
  'hwwnlu36ff': R`$\ce{CO2}$: dipol saling meniadakan, nonpolar`,
  '11r63oesm8r': R`Air: kedua dipol saling menjumlah`,
  '14kma3jnj6e': R`$\ce{H2O}$: dipol saling menjumlah, polar`,
  'sqok1otwgj': R`Kepolaran ikatan ditambah bentuk molekul menentukan apakah seluruh molekul polar.`,
  '15ngjyw9udv': R`<p>Cairan polar tertarik oleh batang bermuatan: aliran air yang tipis membelok ke arah sisir plastik yang telah digosok, sedangkan aliran heksana tidak.</p>`,
  '22wf4fxzi21': R`Apa bentuk molekul $\ce{⟦0⟧}$?`,
  '28n3c8lqx2j': R`Atom pusat memiliki ⟦0⟧ domain ikatan<!--⟦1⟧--> dan ⟦2⟧ pasangan bebas<!--⟦3⟧-->: <b>⟦4⟧</b>, ⟦5⟧.`,
  'mxxpuqir6u': R`Berapa sudut ikatan dalam $\ce{⟦0⟧}$?`,
  'wwjd5yh55a': R`⟦0⟧ pasangan ikatan dan ⟦1⟧ pasangan bebas: ⟦2⟧, <b>⟦3⟧</b>.`,
  '11ouh7r6cmb': R`Apakah $\ce{⟦0⟧}$ molekul polar?`,
  '25c2ov24t7g': R`Bentuknya ⟦0⟧: dipol-dipol ikatannya tidak saling meniadakan, jadi <b>polar</b>.`,
  'seqcfu7bwo': R`Bentuknya ⟦0⟧ dan simetris: dipol-dipol ikatannya saling meniadakan, jadi <b>nonpolar</b>.`,
  'mwuy893m9c': R`Berapa pasangan elektron bebas pada atom pusat $\ce{⟦0⟧}$?`,
  '16mue43afe3': R`$\ce{⟦0⟧}$: ⟦1⟧ domain ikatan dan <b>⟦2⟧</b> pasangan bebas<!--⟦3⟧--> pada atom pusat.`,
  'd7w3l49pv': R`Berapa domain elektron di sekitar atom pusat $\ce{⟦0⟧}$?`,
