  'zxq1f68wx7': R`Mengapa sudut ikatan dalam air lebih kecil daripada dalam metana?`,
  'q6h166z24r': R`Pasangan elektron bebas menolak lebih kuat daripada pasangan ikatan`,
  '1v75zn235sb': R`Oksigen lebih besar daripada karbon`,
  'g4v74rc081': R`Air memiliki ikatan rangkap`,
  '47iuw17va7': R`Atom-atom hidrogen saling menarik`,
  '1itto2pe6gm': R`Dua pasangan bebas mendorong ikatan O–H berdekatan: 104,5° alih-alih 109,5°.`,
  'xcpkc6p9ph': R`CO₂ memiliki ikatan polar. Mengapa molekulnya nonpolar?`,
