  '1g3ups2e58v': R`ikatan hidrogen`,
  'zljw3zshfq': R`H yang terikat pada N, O, atau F tertarik pada pasangan elektron bebas N, O, atau F molekul lain`,
  '8o03t5zhr0': R`yang terkuat di antara ketiganya`,
  '1dcfdmma4ym': R`$\ce{H2O}$, $\ce{NH3}$, $\ce{HF}$, alkohol`,
  'ufb6c393bn': R`Molekul-molekul air yang dihubungkan ikatan hidrogen, digambar dengan garis putus-putus`,
  'uabn5jmxim': R`Ikatan hidrogen (putus-putus) antara molekul air: setiap H dari satu molekul tertarik pada pasangan elektron bebas O molekul lain.`,
  'ia3voxd8yc': R`titik didih (°C)`,
  'iy5xvq5ydl': R`Titik didih hidrida golongan 14 sampai 17: air, hidrogen fluorida, dan amonia jauh lebih tinggi dari kecenderungannya`,
  '1fsag2ml26j': R`Titik didih hidrida golongan 14–17 (CRC Handbook). Dalam setiap golongan, titik didih naik ke bawah seiring bertambahnya elektron (gaya London lebih kuat), tetapi $\ce{H2O}$, $\ce{HF}$, dan $\ce{NH3}$ jauh di atas kecenderungan itu karena ikatan hidrogen. Tanpa ikatan hidrogen, air akan mendidih sekitar −80 °C.`,
  'ykrbhqa3s6': R`Struktur`,
  '1xurynzfy21': R`Titik leleh`,
  '1ioae5lr0bq': R`Menghantarkan listrik?`,
  'a34su6hhg1': R`ion raksasa`,
  '1c2wkgptp12': R`ion`,
  '1u9t2pxgp87': R`saat meleleh atau larut`,
  '2dbc7h0tw8n': R`kovalen raksasa`,
