  '1fge6dwgxvl': R`intan, grafit, $\ce{SiO2}$`,
  '2sbqwh4duv': R`ion positif + elektron terdelokalisasi`,
  '1orqnux5zwg': R`biasanya tinggi`,
  '25vuda1ivl4': R`ya, juga saat padat`,
  '21vclz3pysn': R`molekul sederhana`,
  '1xp9pa1yn8p': R`molekul`,
  'u2sm8bp87d': R`<p>Es mengapung karena ikatan hidrogen menahan molekul air dalam kisi terbuka yang massa jenisnya lebih kecil daripada air cair; itulah sebabnya danau membeku dari permukaan dan ikan dapat bertahan hidup di musim dingin.</p>`,
  '25z5xr9gy9o': R`Jenis struktur apa yang dimiliki ⟦0⟧?`,
  '16zp0n0lb83': R`hanya gaya London`,
  'kn3yp3iya2': R`gaya dipol–dipol (dan gaya London)`,
  '29bt9gq03fz': R`ikatan hidrogen (dan gaya London)`,
  'yns1v0f4y1': R`Jenis gaya antarmolekul terkuat apa di antara molekul-molekul $\ce{⟦0⟧}$?`,
  '1tcfujv2hgy': R`ikatan ion`,
