  'kq72s9wat4': R`$\ce{⟦0⟧}$ memiliki lebih banyak elektron, sehingga gaya Londonnya lebih kuat: ⟦1⟧ °C dibanding ⟦2⟧ °C.`,
  'y7swwgpl0v': R`Mengapa grafit menghantarkan listrik sedangkan intan tidak?`,
  '1s4l5jz7a2u': R`Setiap karbon dalam grafit memiliki satu elektron terdelokalisasi`,
  '19k56xu8s3k': R`Grafit mengandung ion`,
  'kwx5dqdlm1': R`Intan tidak memiliki elektron`,
  '1fgvwf994cl': R`Grafit adalah logam`,
  '12eq4p1ad8m': R`Dalam grafit setiap karbon memakai 3 elektron untuk ikatan; elektron keempat bebas bergerak sepanjang lapisan.`,
  '1789xqukt00': R`Mengapa logam dapat dibengkokkan dan ditempa?`,
  'ff26qg7gf7': R`Lapisan-lapisan ion dapat bergeser sementara lautan elektron tetap mengikatnya`,
