  '1xh58c9cw': R`Ikatan logam lemah`,
  '1ayljtj7wng': R`Logam mengandung molekul`,
  'uq4mivt9cb': R`Elektron terdelokalisasi tetap mengikat ion-ion setelah lapisannya bergeser.`,
  '1zzxk0cbt03': R`Ketika air mendidih, apa yang diputus?`,
