  '27yx5wayv6o': R`kenampakan`,
  'p1uok8w1rr': R`jernih`,
  '14cyr57crjk': R`keruh atau jernih`,
  '1vgj28lh44y': R`keruh`,
  '1l6pni75imw': R`mengendap bila didiamkan?`,
  '2ff3cbt79eb': R`dapat disaring kertas saring?`,
