  '1l16le2kqha': R`air berlumpur`,
  '200xe2pgcm3': R`Efek Tyndall: berkas cahaya tidak terlihat dalam larutan tetapi terlihat dalam koloid`,
  '1xtyoopcj9p': R`<b>Efek Tyndall</b>: partikel koloid menghamburkan cahaya, sehingga berkas cahaya terlihat melewati koloid tetapi tidak melewati larutan sejati. Contohnya lampu mobil di tengah kabut dan berkas sinar matahari di ruangan berdebu.`,
  '1hzocmlsqwg': R`Fase terdispersi`,
  '7b7wvhgls1': R`dalam medium`,
  '199yxveilmj': R`sol`,
  'a3l8zpxk92': R`cat, tinta, darah`,
  '2c76b0ol3d2': R`emulsi`,
  '3db0xdb9fn': R`susu, mayones`,
  '4h6lpz3fyo': R`buih`,
  '21oxich7gnn': R`krim kocok, busa sabun`,
  '3zoogndh1g': R`aerosol cair`,
  '8417n8lwd8': R`kabut, awan, hairspray`,
  'uxrdvyjach': R`aerosol padat`,
  't1lbo2gwlj': R`asap, debu`,
  '28u52s0ai9p': R`gel`,
  'woy4akzj8g': R`agar-agar, keju, mentega`,
  '1ba3oddo1ds': R`busa padat`,
  '1bj4gpv95vw': R`batu apung, marshmallow`,
  'gly9vyl8bw': R`sol padat`,
  '1zcpi8p0wv5': R`kaca berwarna, beberapa paduan logam`,
  '28m0odivwqf': R`<p>Sifat-sifat lain: <b>gerak Brown</b> (partikel koloid bergerak acak karena ditumbuk molekul pelarut secara tidak seimbang), <b>adsorpsi</b> (partikel menyerap ion di permukaannya; dipakai dalam penjernihan air dengan tawas), <b>koagulasi</b> (penambahan elektrolit atau pemanasan membuat partikel menggumpal, seperti pada pembuatan tahu atau karet dari lateks), dan <b>dialisis</b> (ion menembus membran, partikel koloid tidak; dipakai pada cuci darah). <b>Pengemulsi</b> seperti sabun atau kuning telur (lesitin) mencegah emulsi memisah.</p>`,
  '14f9tzdqa84': R`<p>Koloid dibuat dengan cara <b>dispersi</b> (memecah partikel besar, mis. menggerus, atau mengocok minyak dengan sabun) atau <b>kondensasi</b> (menggabungkan partikel kecil, mis. hidrolisis $\ce{FeCl3}$ dalam air panas membentuk sol $\ce{Fe(OH)3}$).</p>`,
  '6nweb88w30': R`mayones`,
  '56ds8fcv3x': R`kabut`,
  '1v5nx3vcd0p': R`asap`,
  'j3mxf65e1a': R`krim kocok`,
  '1i2ilmr2yi': R`agar-agar`,
  '22b9clzzb9d': R`tinta`,
  '151xjixfed8': R`mentega`,
  'w7lp06ilam': R`cat`,
  '26l9aq0xvzm': R`Jenis koloid apakah ⟦0⟧?`,
