  'jlnzlj0z3w': R`gelatin`,
  '14hu26whgtk': R`pasir dalam air`,
  'wnd79bzwwk': R`kapur dalam air`,
  '2banp3j42rw': R`Apakah ⟦0⟧ termasuk larutan, koloid, atau suspensi?`,
  'gc00isg1ml': R`berkas lampu mobil terlihat di tengah kabut`,
  'zksr1o7e8a': R`efek Tyndall`,
