  '1skngtux7so': R`gerak Brown`,
  'lbzc89usn1': R`sabun menghilangkan noda minyak dari pakaian`,
  '9qnyn8fhm9': R`emulsifikasi`,
  '58bk2h3456': R`Sifat koloid manakah yang menjelaskan hal ini: ⟦0⟧?`,
  '1oz96rwivju': R`Partikel terdispersinya berukuran sekitar ⟦0⟧. Campuran jenis apakah itu?`,
  'vc30flz6bh': R`Di bawah 1 nm larutan, 1–1000 nm koloid, di atasnya suspensi: <b>⟦0⟧</b>.`,
