  '21sajsck8ow': R`makin basa →`,
  'bimfu0wxee': R`Skala pH dari 0 sampai 14 dengan warna indikator universal dan contoh sehari-hari dari air aki sampai pembersih saluran`,
  'u1aaqhe6hp': R`Skala pH dengan warna indikator universal dan nilai khas (US EPA dan USGS). Setiap selisih 1 satuan pH berarti perubahan konsentrasi $\ce{H+}$ sepuluh kali: air jeruk nipis (pH 2) memiliki $\ce{H+}$ 1000 kali lebih banyak daripada kopi (pH 5).`,
  '1af8prwga1x': R`Dalam asam`,
  'yqm7h6vb5o': R`Dalam basa`,
  'smxhxmjpnh': R`lakmus`,
  '1p3fu9b5oob': R`fenolftalein`,
