  'qec4sw83pz': R`indikator universal`,
  'ftri94yztf': R`merah → jingga → kuning`,
  'lr89rp10dw': R`biru → ungu`,
  '2c60m9om3a': R`ekstrak kubis ungu atau kunyit`,
  '271qjnddux1': R`merah / kuning`,
  '5lhy0qr0bs': R`hijau / merah kecokelatan`,
  '4tdur9xse8': R`<p><b>Penetralan:</b> asam + basa → garam + air. Persamaan ionnya selalu $\ce{H+(aq) + OH-(aq) -> H2O(l)}$. Reaksi asam lainnya:</p><p>asam + logam → garam + hidrogen: $\ce{Zn + 2HCl -> ZnCl2 + H2}$<br>asam + karbonat → garam + air + karbon dioksida: $\ce{CaCO3 + 2HCl -> CaCl2 + H2O + CO2}$<br>asam + oksida logam → garam + air: $\ce{CuO + H2SO4 -> CuSO4 + H2O}$</p>`,
  '16gvplvac3k': R`Asam`,
  'v5ojuyzcz0': R`Nama garamnya`,
  '1ixiy526yg0': R`asam klorida`,
  '1kbglrncmsp': R`klorida`,
  '1q5fc8ggisg': R`asam sulfat`,
  '8e8zvimv5o': R`sulfat`,
  '26l87lp0b4j': R`asam nitrat`,
  '1pf81t5msfu': R`nitrat`,
  '1p5v8of114k': R`asam etanoat`,
  'u7fuobgnnv': R`etanoat`,
  '2l6nxo1oj3': R`<p>Uji hidrogen: bara kayu yang menyala memberi letupan "pop". Uji karbon dioksida: gas ini mengeruhkan air kapur. Penetralan sehari-hari: obat maag (antasida) untuk asam lambung, kapur tohor ($\ce{CaO}$) untuk tanah asam, pasta gigi melawan asam yang dibuat bakteri.</p>`,
  '1r061252506': R`asam`,
  '1hmng131vvn': R`basa`,
  'r7j7gku88n': R`⟦0⟧ memiliki pH sekitar ⟦1⟧. Apakah zat itu asam, netral, atau basa?`,
  'iy95orambu': R`Di bawah 7 asam, 7 netral, di atas 7 basa: <b>⟦0⟧</b>.`,
  '1v3ev24xofc': R`Berapa kali lebih banyak ion $\ce{H+}$ dalam larutan pH ⟦0⟧ dibanding larutan pH ⟦1⟧?`,
  '1lm484vk7jp': R`Setiap satuan pH adalah faktor 10: $10^{⟦0⟧} = ⟦1⟧$.`,
  '1yg19o6o04l': R`basa`,
  '36tvxe0s1n': R`asam`,
  '6m8l29btzi': R`Apa warna ⟦0⟧ dalam ⟦1⟧?`,
