  'soolynwsvu': R`seng sulfat + hidrogen`,
  '8e08zgtxrw': R`magnesium + asam klorida`,
  '20g2fsqtr60': R`magnesium klorida + hidrogen`,
  '2c8hedybet3': R`kalsium karbonat + asam klorida`,
  '1amf5cu8wj2': R`kalsium klorida + air + karbon dioksida`,
  '1jksv54suxd': R`natrium hidroksida + asam nitrat`,
  '1vdx7ilnyw0': R`natrium nitrat + air`,
  '1ohazez1shm': R`tembaga(II) oksida + asam sulfat`,
