  '16wf5kfzn4t': R`kalium hidroksida + asam klorida`,
  'jt6u3d2qbz': R`kalium klorida + air`,
  'w1cuvg7l8r': R`Apa hasil reaksi ⟦0⟧?`,
  '1f4zn6fxjw6': R`Ion apa yang dihasilkan semua asam dalam air?`,
  'ot3dmczl9t': R`Ion hidrogen, $\ce{H+}$ (dalam air $\ce{H3O+}$).`,
  '2dcfdq8xrr8': R`Apa persamaan ion untuk setiap penetralan asam oleh basa?`,
