  '4r240h3lsz': R`udara + air: berkarat`,
  '1axk27wuz6u': R`air mendidih + minyak: tidak berkarat`,
  '1od1apqj1up': R`udara kering (zat pengering): tidak berkarat`,
  'v7majn9s4q': R`Tiga tabung reaksi berisi paku besi: dalam udara dan air paku berkarat; dalam air yang telah dididihkan di bawah minyak dan dalam udara kering tidak`,
  '1rywvhowu80': R`Percobaan klasik: besi hanya berkarat jika ada <b>oksigen dan air sekaligus</b>. Pendidihan mengusir udara terlarut dan lapisan minyak mencegahnya masuk kembali; kalsium klorida menjaga udara tetap kering. Air garam mempercepat perkaratan.`,
  '1xw3oxm9rz1': R`<p>Perkaratan adalah proses elektrokimia. Sebagian permukaan besi bertindak sebagai anode: $\ce{Fe -> Fe^2+ + 2e-}$. Elektron mengalir melalui logam ke tempat oksigen direduksi: $\ce{O2 + 2H2O + 4e- -> 4OH-}$. $\ce{Fe^2+}$ dan $\ce{OH-}$ membentuk $\ce{Fe(OH)2}$, yang teroksidasi lebih lanjut menjadi karat.</p>`,
