  '1q1r3e7jy3q': R`baja tahan karat mengandung kromium dan nikel, yang membentuk lapisan oksida pelindung`,
  '2eelcn0gpwt': R`sendok garpu, bak cuci`,
  'xscoi82y14': R`proteksi katodik dengan arus listrik`,
