  '256uoix6fk9': R`jaringan pipa, jembatan`,
  '268wcd5cbbt': R`<p>Korosi menelan biaya sekitar 3–4% PDB dunia setiap tahun (NACE International, 2016). Aluminium, seng, dan kromium tampak reaktif di atas kertas tetapi tahan korosi karena lapisan oksida yang tipis dan rapat melindunginya.</p>`,
  '1u8cnjyooqy': R`paku besi dalam air yang telah dididihkan dan ditutup minyak`,
