  'awceu02rx5': R`Rumus struktur lengkap menunjukkan setiap atom dan ikatan. Alkana hanya memiliki ikatan tunggal; alkena memiliki ikatan rangkap dua C=C; alkuna memiliki ikatan rangkap tiga C≡C.`,
  '1j5oa91vhaf': R`Deret`,
  '1w0phx0f066': R`Rumus umum`,
