  '705v4m2xtf': R`<p>Gugus yang dapat membentuk ikatan hidrogen (–OH, –COOH, –NH₂) menaikkan titik didih dan kelarutan dalam air: etanol ($M_r$ 46) mendidih pada 78 °C, propana ($M_r$ 44) pada −42 °C. Kelarutan berkurang jika rantai hidrokarbon makin panjang. Asam karboksilat adalah asam lemah; amina adalah basa lemah.</p>`,
