  '1f4oy5pxoyk': R`Ikatan C=C tidak dapat berputar, sehingga but-2-ena memiliki dua isomer <b>cis/trans</b> (geometri). Syaratnya, setiap karbon ikatan rangkap mengikat dua gugus yang berbeda.`,
  '1s249xaah9': R`<p>Atom karbon yang mengikat empat gugus yang <b>berbeda</b> disebut <b>kiral</b>. Dua bentuk bayangan cerminnya tidak dapat ditumpangtindihkan, seperti tangan kiri dan kanan: keduanya adalah <b>isomer optis</b> (enantiomer). Keduanya memutar cahaya terpolarisasi ke arah berlawanan dan dapat bekerja sangat berbeda di dalam tubuh: satu bentuk karvon berbau daun mint, bentuk lainnya berbau jintan.</p>`,
  '20hfgh4q7ke': R`Karbon kiral dengan empat gugus berbeda`,
  '1hf09a6p70x': R`satu enantiomer`,
  '2g1fvzx8fqo': R`Bayangan cerminnya`,
  'kwgrsmb8vv': R`bayangan cerminnya`,
  'ndbtiaikvg': R`Empat gugus berbeda (empat warna) di sekitar karbon: molekul dan bayangan cerminnya tidak sama, bagaimanapun diputar.`,
  'okp6widsjj': R`<p>Talidomid (1950-an–60-an) adalah peringatan terkenal: satu enantiomer meredakan mual pada kehamilan, enantiomer lainnya menyebabkan cacat lahir. Kini produsen obat menguji setiap enantiomer secara terpisah.</p>`,
