  'mdu6dtjbr5': R`Menghubungkan gugus-gugus fungsi. Alkohol primer teroksidasi menjadi aldehida, lalu asam karboksilat; alkohol sekunder menjadi keton; alkohol tersier tahan oksidasi. Dikromat yang diasamkan berubah dari jingga menjadi hijau ketika mengoksidasi alkohol.`,
  '287f45z1ego': R`<p>Etanol untuk bahan bakar dan minuman juga dibuat dengan <b>fermentasi</b> gula oleh ragi: $\ce{C6H12O6 -> 2C2H5OH + 2CO2}$ pada sekitar 35 °C tanpa udara.</p>`,
