  'o0evveec94': R`Setiap karbon memakai tiga elektron untuk ikatan σ dan menyumbangkan elektron keempatnya ke cincin enam elektron <b>terdelokalisasi</b> di atas dan di bawah bidang cincin, digambarkan sebagai lingkaran.`,
  '1q36nooyxco': R`<p>Delokalisasi membuat benzena sekitar 150 kJ/mol lebih stabil daripada "sikloheksatriena". Karena itu benzena lebih menyukai <b>substitusi</b>, yang mempertahankan cincinnya, daripada adisi. Elektrofil (akseptor pasangan elektron) menyerang cincin yang kaya elektron:</p>`,
