  'fhnyiwehtm': R`Beberapa senyawa aromatik penting: fenol (disinfektan, resin), metilbenzena (pelarut), asam benzoat (pengawet makanan E210), anilina (zat warna).`,
  '1im3jdrqvek': R`<p>Benzena sendiri bersifat karsinogenik, sehingga metilbenzena dipakai sebagai pelarut penggantinya. Cincin aromatik banyak terdapat di alam dan obat-obatan: aspirin, parasetamol, asam amino seperti fenilalanina, dan basa-basa DNA.</p>`,
  '25w1fpijysf': R`Mengapa benzena tidak menghilangkan warna air brom seperti alkena?`,
  '1to9gsjk71c': R`Elektron terdelokalisasinya membuatnya stabil; adisi akan merusak kestabilan ini`,
  'b28t86xms5': R`Benzena tidak memiliki ikatan rangkap atau elektron di antara karbonnya`,
