  '2aww2b48qtx': R`<b>Polimerisasi adisi:</b> ikatan C=C terbuka dan monomer-monomer tersambung menjadi rantai; tidak ada zat lain yang terbentuk. Unit ulangnya ditulis dalam kurung dengan $n$ (sering beberapa ribu).`,
