  '18pp2m6xoy0': R`<p><b>Polimer kondensasi</b> terbentuk ketika monomer yang memiliki dua gugus fungsi bergabung dan melepaskan molekul kecil (biasanya air) pada setiap sambungan. Diasam + diol menghasilkan <b>poliester</b> (PET untuk botol dan serat); diasam + diamina menghasilkan <b>poliamida</b> (nilon, Kevlar). Protein (dari asam amino), pati dan selulosa (dari glukosa), serta DNA adalah polimer kondensasi alami.</p>`,
