  'xl06kkdlj5': R`Bagaimana dunia memakai plastik (UNEP, <i>Single-use plastics</i>, 2018). Kemasan, yang sebagian besar hanya sekali pakai, merupakan bagian terbesar.`,
  '1tmnqj3kspd': R`<p>Kebanyakan polimer adisi tidak dapat terurai secara hayati: bertahan berabad-abad dan hancur menjadi mikroplastik. Solusinya: kurangi dan gunakan ulang, daur ulang mekanis (kode resin 1–7 pada produk membedakan jenisnya), daur ulang kimia, dan polimer terurai hayati seperti PLA dari pati jagung.</p>`,
