  '1sn4m1v5u6o': R`Glukosa adalah bahan bakar utama sel: $\ce{C6H12O6 + 6O2 -> 6CO2 + 6H2O}$, $\Delta H = -2803$ kJ/mol (respirasi). Dalam air, glukosa sebagian besar berbentuk cincin beranggota enam ini.`,
