  '17584vza1i6': R`<p>Nilai energi pada label makanan: karbohidrat dan protein sekitar 17 kJ/g, lemak sekitar 37 kJ/g; itulah sebabnya lemak menjadi cadangan energi tubuh yang ringkas.</p>`,
