  '3x5ajmidem': R`bilangan oksidasi beragam`,
  '16btirusy15': R`Fe: +2 dan +3; Mn: +2 sampai +7 ($\ce{MnO4-}$ bernilai +7)`,
  '1sa9y738jqm': R`senyawa berwarna`,
  '1b2d8zxqym4': R`$\ce{CuSO4.5H2O}$ biru, $\ce{Fe^3+}$ kuning kecokelatan, $\ce{MnO4-}$ ungu`,
  '24m3t1fqxj7': R`ion kompleks`,
  '16lf38gv5tu': R`$\ce{[Cu(H2O)6]^2+}$, $\ce{[Cu(NH3)4(H2O)2]^2+}$ biru tua`,
  '29a669rguh3': R`katalis`,
  '21h270imnj7': R`Fe (Haber), $\ce{V2O5}$ (Kontak), Pt/Rh (konverter katalitik), Ni (hidrogenasi)`,
  'wiipalu8j1': R`hijau pucat`,
  'lwkvm01khi': R`kuning kecokelatan`,
  'ni4vcuiifl': R`ungu`,
  '42w3hbqlre': R`jingga`,
  '1cztwq15gbv': R`Warna ion logam transisi dalam air: tembaga biru, besi dua plus hijau pucat, besi tiga plus kuning kecokelatan, dan seterusnya; seng tidak berwarna`,
  '1csqvi442ua': R`Warna khas ion logam transisi dalam air. $\ce{Zn^2+}$ ($d^{10}$ penuh) dan $\ce{Sc^3+}$ ($d^0$) tidak berwarna.`,
  '118upeko3y6': R`<p>Dalam <b>ion kompleks</b>, <b>ligan</b> (molekul atau ion yang memiliki pasangan elektron bebas, seperti $\ce{H2O}$, $\ce{NH3}$, $\ce{Cl-}$, $\ce{CN-}$) membentuk ikatan koordinasi dengan ion logam pusat. Jumlah ikatan koordinasi disebut <b>bilangan koordinasi</b>: 6 menghasilkan kompleks oktahedral, 4 tetrahedral atau segi empat datar, 2 linear ($\ce{[Ag(NH3)2]+}$).</p>`,
  '9nuqub488m': R`Kompleks oktahedral dengan enam ligan air`,
  'c5nydjro3v': R`$\ce{[Cu(H2O)6]^2+}$: oktahedral, 6`,
  'bp05njmrse': R`Kompleks tetrahedral dengan empat ligan klorida`,
  '14t1t20bt4l': R`$\ce{[CuCl4]^2-}$: tetrahedral, 4`,
  '1695jdh33to': R`Kompleks linear dengan dua ligan amonia`,
  's0fhoxdlco': R`$\ce{[Ag(NH3)2]+}$: linear, 2`,
  '1zwpknh7hl': R`Bentuk ion kompleks (ion logam di tengah).`,
  '6polip9zv6': R`<p>Warna muncul karena ligan memecah orbital $d$ menjadi dua tingkat energi. Kompleks menyerap cahaya yang energinya sebesar celah itu dan kita melihat warna komplementernya: $\ce{[Cu(H2O)6]^2+}$ menyerap cahaya jingga-merah, sehingga tampak biru. Mengganti ligan mengubah celah dan warnanya.</p>`,
  'o7x1gsqet2': R`Berapa bilangan oksidasi ⟦0⟧ dalam $\ce{⟦1⟧}$?`,
  'dnh2422cpv': R`Jumlahkan muatan ligan (H₂O, NH₃: 0; Cl⁻, CN⁻: −1) dan samakan dengan muatan total: <b>+⟦0⟧</b>.`,
  '1kxrto02xd8': R`Berapa bilangan koordinasi dalam $\ce{⟦0⟧}$?`,
  'uhn46txeje': R`⟦0⟧ ligan masing-masing membentuk satu ikatan koordinasi: <b>⟦1⟧</b>.`,
  '1qzz9nesqnh': R`Apa bentuk $\ce{⟦0⟧}$?`,
  '1nizh3917hx': R`Bilangan koordinasi ⟦0⟧: <b>⟦1⟧</b>.`,
  '2jumk45il5': R`Apa warna larutan $\ce{⟦0⟧}$ dalam air?`,
