  '2567u8ov6ws': R`platina dan rodium`,
  '75k2us8gfv': R`penguraian hidrogen peroksida`,
  'bidkx2z4nw': R`mangan(IV) oksida`,
  '261a6ry66ei': R`Katalis apa yang dipakai untuk ⟦0⟧?`,
  'uay8semd5e': R`Apa itu ligan?`,
  'acxocetcao': R`Molekul atau ion dengan pasangan elektron bebas yang membentuk ikatan koordinasi dengan ion logam`,
  'k0p1dyf3fb': R`Ion logam positif`,
  '1c9vgiqjae9': R`Molekul apa pun dalam larutan`,
  '2aaawt46m6d': R`Salah satu jenis katalis`,
  'd3z2xiam61': R`Mengapa senyawa Zn²⁺ berwarna putih atau tidak berwarna?`,
  '15dumlbsbc3': R`Zn²⁺ memiliki subkulit d penuh, sehingga tidak ada lompatan elektron d–d`,
  'ya36bgonqa': R`Seng bukan logam`,
