  'kjdaxvflo': R`Deret kereaktifan dari kalium yang paling reaktif sampai emas yang paling tidak reaktif`,
  '1qc7u0mwo1t': R`Deret kereaktifan: paling reaktif (K) di kiri, paling tidak reaktif (Au) di kanan. Logam dapat mendesak logam mana pun di sebelah kanannya dari senyawanya: $\ce{Fe + CuSO4 -> FeSO4 + Cu}$.`,
  '1izsp3gsltb': R`Cara pengambilan`,
