  '16tk55ei8i9': R`gas buang`,
  '2fj1gt2m1pi': R`terak`,
  'cssvfshnr': R`besi cair`,
  'emca7uoakr': R`Tanur tinggi: bahan baku masuk dari atas, udara panas ditiupkan di dekat dasar, besi cair dan terak dikeluarkan`,
  '17hx7041jkp': R`Tanur tinggi. Kokas terbakar menghasilkan panas dan karbon monoksida, yang mereduksi besi(III) oksida menjadi besi. Batu kapur mengikat pengotor pasir menjadi terak: $\ce{CaCO3 -> CaO + CO2}$, $\ce{CaO + SiO2 -> CaSiO3}$.`,
  'rzywpn7tdc': R`<p><b>Paduan logam (aloi)</b> adalah campuran logam dengan unsur lain. Atom-atom yang ukurannya berbeda mengganggu lapisan-lapisan logam sehingga lebih sukar bergeser: paduan lebih keras dan kuat. Baja (besi + karbon; baja tahan karat ditambah Cr dan Ni), kuningan (Cu + Zn), perunggu (Cu + Sn), solder (Sn + Pb atau Ag), duralumin (Al + Cu), emas 18 karat (75% Au).</p>`,
  '27ssn0az5p3': R`<p>Daur ulang aluminium hanya memerlukan sekitar 5% energi yang diperlukan untuk mengambilnya dari bauksit (International Aluminium Institute), serta menghemat bijih dan mengurangi limbah.</p>`,
  '132dwa6w32z': R`⟦0⟧ lebih tinggi dalam deret kereaktifan.`,
  '1i332bzt11u': R`Apakah ⟦0⟧ dapat mendesak ⟦1⟧ dari larutan garamnya?`,
  '11r11xtbyzy': R`⟦0⟧ lebih reaktif: <b>ya</b>.`,
