  '25rymer5znc': R`gama`,
  '1aqt31fehvd': R`Daya tembus: alfa dihentikan kertas, beta oleh aluminium, gama hanya dilemahkan timbal tebal`,
  'vfeh2qfi1f': R`Alfa paling kuat mengionkan tetapi daya tembusnya paling lemah; gama paling kuat daya tembusnya.`,
  'pabdgoic1n': R`<p>Dalam <b>persamaan reaksi inti</b>, nomor massa dan nomor atom harus setara di kedua ruas: $$^{238}_{92}\mathrm{U} \to {}^{234}_{90}\mathrm{Th} + {}^{4}_{2}\mathrm{He} \qquad ^{14}_{6}\mathrm{C} \to {}^{14}_{7}\mathrm{N} + {}^{0}_{-1}e$$</p>`,
  'squpy3z0nq': R`peluruhan β⁻ (kelebihan neutron)`,
  '1lyxkt9wtgi': R`peluruhan β⁺ / penangkapan elektron`,
  '1pcc369sgx9': R`peluruhan α (inti berat)`,
  'oupsednuyx': R`Pita kestabilan: inti stabil berada dekat N sama dengan Z untuk unsur ringan dan di atasnya untuk unsur yang lebih berat`,
  'vo7t7xpaai': R`<b>Pita kestabilan</b>. Inti ringan yang stabil memiliki $N \approx Z$; inti yang lebih berat memerlukan lebih banyak neutron (timbal-208: 126 neutron, 82 proton). Inti di atas pita meluruh dengan β⁻, di bawahnya dengan β⁺, dan inti sangat berat ($Z > 83$) dengan α.`,
  '1upodcd2005': R`waktu paruh`,
  '1h52p0h8511': R`% tersisa`,
  'v1lcs9c088': R`Peluruhan radioaktif: jumlahnya menjadi setengah setiap waktu paruh`,
  '1yx24fdrlg8': R`<b>Waktu paruh</b> $t_{1/2}$ adalah waktu yang diperlukan agar separuh inti radioaktif meluruh. Setelah $n$ waktu paruh, bagian yang tersisa adalah $\left(\frac{1}{2}\right)^n$. Karbon-14 ($t_{1/2}$ = 5730 tahun) dipakai untuk menentukan umur peninggalan arkeologi.`,
  '162ya41kv5c': R`<p><b>Fisi:</b> inti berat (U-235) membelah setelah menyerap neutron, melepaskan energi dan neutron baru (reaksi berantai) — pembangkit listrik tenaga nuklir. <b>Fusi:</b> inti-inti ringan bergabung, seperti di Matahari: $^{2}_{1}\mathrm{H} + {}^{3}_{1}\mathrm{H} \to {}^{4}_{2}\mathrm{He} + {}^{1}_{0}n$. Keduanya melepaskan energi karena sedikit massa diubah menjadi energi: $E = mc^2$.</p>`,
  '20pwwbuujtg': R`<p>Kegunaan: perunut medis (Tc-99m, 6 jam) dan radioterapi (Co-60), iodin-131 untuk pengobatan tiroid, detektor asap (Am-241, α), sterilisasi makanan dan alat (γ), pengukur ketebalan (β). Bahaya: radiasi merusak DNA, sehingga paparan dibuat serendah mungkin dengan pelindung, jarak, dan waktu singkat.</p>`,
  '2bi2oa1vlbk': R`$^{⟦0⟧}_{⟦1⟧}\mathrm{⟦2⟧}$ mengalami peluruhan ⟦3⟧. Inti apa yang terbentuk?`,
  'kw1jseunwd': R`Alfa: $A - 4$, $Z - 2$ → $^{⟦0⟧}_{⟦1⟧}\mathrm{⟦2⟧}$.`,
  '15vg82labk2': R`Beta: $A$ tetap, $Z + 1$ → $^{⟦0⟧}_{⟦1⟧}\mathrm{⟦2⟧}$.`,
  '26zvgnb9iqb': R`⟦0⟧-⟦1⟧ memiliki waktu paruh ⟦2⟧ ⟦3⟧. Berapa sisa sampel ⟦4⟧ mg setelah ⟦5⟧ ⟦6⟧ (dalam mg)?`,
  '2ax8fiw47fe': R`⟦0⟧ kali waktu paruh: $⟦1⟧ \times (\tfrac12)^{⟦2⟧} = ⟦3⟧$ mg.`,
  '234pcroat8j': R`Suatu sampel tinggal memiliki ⟦0⟧% inti radioaktif semula. Waktu paruhnya ⟦1⟧ tahun. Berapa umurnya (dalam tahun)?`,
  '2tgeh0cc72': R`⟦0⟧% = $(\tfrac12)^{⟦1⟧}$: ⟦2⟧ kali waktu paruh $= ⟦3⟧$ tahun.`,
  '36l4ifqa0i': R`dihentikan oleh selembar kertas`,
