  '1io1ytc8yoo': R`permukaan Bumi menghangat`,
  '1zlg9rfvop9': R`Efek rumah kaca: sinar matahari menghangatkan permukaan; permukaan memancarkan inframerah, yang sebagian diserap gas rumah kaca dan dipancarkan kembali ke bawah`,
  '1s7515xt0ju': R`<b>Efek rumah kaca</b>. Gas rumah kaca ($\ce{CO2}$, $\ce{CH4}$, $\ce{H2O}$, $\ce{N2O}$) menyerap radiasi inframerah dari permukaan yang hangat dan memancarkan sebagian kembali ke bawah. Tanpa gas-gas ini suhu rata-rata Bumi sekitar −18 °C, bukan +15 °C.`,
  '1xyfnbm06l2': R`Karbon dioksida di Mauna Loa naik dari 317 bagian per juta pada 1960 menjadi 421 pada 2023`,
  '26pdhn8zo2o': R`Rata-rata tahunan $\ce{CO2}$ di Observatorium Mauna Loa, Hawaii (NOAA Global Monitoring Laboratory): dari 317 ppm pada 1960 menjadi 421 ppm pada 2023, terutama akibat pembakaran bahan bakar fosil dan penggundulan hutan. Sebelum industrialisasi, kadarnya sekitar 280 ppm.`,
