  'lov7ohkgrn': R`kulkas dan aerosol lama`,
  '1649fxaxd3p': R`merusak lapisan ozon`,
  '1udpubyqz2k': R`<p><b>Hujan asam</b>: $\ce{SO2}$ dan $\ce{NO2}$ larut dalam air hujan membentuk asam sulfat dan asam nitrat (pH di bawah 5,6). Hujan asam merusak hutan, danau, dan bangunan dari batu kapur: $\ce{CaCO3 + H2SO4 -> CaSO4 + H2O + CO2}$. Solusinya: desulfurisasi gas buang, bahan bakar rendah belerang, konverter katalitik ($\ce{2CO + 2NO -> 2CO2 + N2}$).<br><b>Lapisan ozon</b>: $\ce{O3}$ di stratosfer menyerap sinar UV yang berbahaya. Atom klorin dari CFC merusaknya melalui reaksi berantai; Protokol Montreal 1987 melarang CFC dan lapisan ozon perlahan pulih.</p>`,
  'hayc46z4pq': R`penyaringan kasar: buang benda besar`,
  '1xrrc8196v3': R`koagulasi dengan tawas: partikel kecil menggumpal`,
  'jbdh0bpjvo': R`sedimentasi: gumpalan mengendap`,
