  '234fopgeowx': R`klorinasi (atau UV/ozon): bunuh mikroba`,
  '2cdy9gezysj': R`Tahap pengolahan air minum: penyaringan kasar, koagulasi, sedimentasi, filtrasi, dan klorinasi`,
  '1j1serufzff': R`Pengolahan air minum. Desalinasi (distilasi atau osmosis balik) dipakai di daerah yang kekurangan air tawar.`,
  'j0a5lkhyb7': R`<p><b>Kimia hijau</b> (Anastas dan Warner, 1998) bertujuan merancang proses yang mencegah limbah, memiliki ekonomi atom tinggi, memakai pelarut yang lebih aman dan bahan baku terbarukan, katalis alih-alih pereaksi berlebih, serta hemat energi.</p>`,
  '1eabxlshqfy': R`belerang dioksida`,
  '1s4is4pm0pk': R`hujan asam`,
  '28tf24rnurw': R`mengurangi kemampuan darah mengangkut oksigen`,
