  'drjappqawt': R`Apa dampak utama ⟦0⟧ terhadap lingkungan atau kesehatan?`,
  '2fuxhgeu7ia': R`$\ce{CO2}$ di Mauna Loa ⟦0⟧ ppm pada ⟦1⟧ dan ⟦2⟧ ppm pada ⟦3⟧. Berapa kenaikan rata-rata per tahun (dalam ppm)?`,
