addT('id', {
  '2cfbrzoynpf': R`<p>Karbon hanya memiliki dua elektron tidak berpasangan ($2s^2\,2p^2$), tetapi metana memiliki empat ikatan C–H yang identik dengan sudut 109,5°. <b>Hibridisasi</b> menjelaskannya: orbital $2s$ dan $2p$ bercampur membentuk <b>orbital hibrida</b> baru yang setara.</p>
⟦0⟧
⟦1⟧
<h3>Orbital molekul</h3>
<p>Dalam <b>teori orbital molekul (OM)</b>, orbital-orbital atom bergabung menjadi orbital molekul yang tersebar di seluruh molekul: OM <b>ikatan</b> yang sefase (energi lebih rendah) dan OM <b>antiikatan</b> yang berlawanan fase (*, energi lebih tinggi). Elektron mengisi OM menurut prinsip Aufbau, larangan Pauli, dan aturan Hund.</p>
⟦2⟧
⟦3⟧
⟦4⟧`,
  '1ca5jee82gd': R`Hibrida`,
  'cyajzihhoa': R`Campuran dari`,
  '14swhkscddn': R`Jumlah`,
  '79gcobv65u': R`Geometri`,
  'tm8tb4smzb': R`tetrahedral, 109,5°`,
  '1sxhcp9ycwt': R`$\ce{CH4}$, intan`,
  'gbf2ec9uhs': R`segitiga datar, 120°`,
  '1xgcalqoty2': R`$\ce{C2H4}$, grafit, benzena`,
  '176ov16bect': R`linear, 180°`,
  '1ag6empivwr': R`<p>Tumpang tindih orbital secara ujung-ke-ujung menghasilkan <b>ikatan σ</b> (kerapatan elektron sepanjang sumbu); tumpang tindih orbital p sejajar secara sisi-ke-sisi menghasilkan <b>ikatan π</b> (kerapatan di atas dan di bawah sumbu). Ikatan tunggal adalah σ; ikatan rangkap dua σ + π; ikatan rangkap tiga σ + 2π. Ikatan π mencegah rotasi (isomer cis/trans).</p>`,
  '19ofv9tnsq1': R`atom`,
  '6ox44efms9': R`Diagram orbital molekul oksigen: dua elektron tidak berpasangan di orbital pi bintang`,
  '1xhauys20i6': R`Diagram OM $\ce{O2}$ (12 elektron valensi). Dua elektron terakhir masuk satu per satu ke dua orbital π*2p, sehingga $\ce{O2}$ memiliki dua elektron tidak berpasangan: bersifat <b>paramagnetik</b> (oksigen cair menempel pada magnet), hal yang tidak dapat dijelaskan struktur Lewis O=O.`,
  '15nmra6qeaf': R`<p>$$\text{orde ikatan} = \frac{(\text{elektron ikatan}) - (\text{elektron antiikatan})}{2}$$ $\ce{O2}$: $\frac{8 - 4}{2} = 2$; $\ce{N2}$: 3; $\ce{He2}$: 0, sehingga tidak ada. Orde ikatan lebih tinggi berarti ikatan lebih pendek dan lebih kuat.</p>`,
  '1sx3n6o7w7d': R`<p>Untuk $\ce{B2}$, $\ce{C2}$, dan $\ce{N2}$, orbital σ2p terletak di atas pasangan π2p (pencampuran s–p); mulai $\ce{O2}$, σ2p terletak di bawahnya. Itulah sebabnya $\ce{B2}$ paramagnetik.</p>`,
  '5a0jqjm96s': R`Apa hibridisasi atom pusat dalam $\ce{⟦0⟧}$⟦1⟧?`,
  '28wqis27hyn': R`Hitung domain elektron: 4 → sp³, 3 → sp², 2 → sp. Di sini: <b>⟦0⟧</b>.`,
  '1fo57jevmf2': R`Berapa ikatan σ dalam $\ce{⟦0⟧}$?`,
  '1mk2knriwcp': R`Setiap ikatan memiliki satu σ; ikatan rangkap dua dan tiga menambah ikatan π: ⟦0⟧ σ dan ⟦1⟧ π.`,
  'msu5ld0om4': R`Berapa ikatan π dalam $\ce{⟦0⟧}$?`,
  '841mf6s43l': R`⟦0⟧ σ dan ⟦1⟧ π.`,
  '2w8mcthav2': R`Gunakan teori OM: berapa orde ikatan $\ce{⟦0⟧}$ (⟦1⟧ elektron valensi)?`,
  'zzicmzvncx': R`Isi OM dengan ⟦0⟧ elektron; (ikatan − antiikatan)/2 = <b>⟦1⟧</b>.`,
  '1xplc2affcy': R`Apakah $\ce{⟦0⟧}$ paramagnetik (ada elektron tidak berpasangan) atau diamagnetik?`,
  'ik0sixdrl0': R`paramagnetik`,
  'ur2gpw6zn': R`diamagnetik`,
  'f4r02djfw8': R`Tingkat terisi tertingginya berupa pasangan π yang setara dengan satu elektron di masing-masing: <b>paramagnetik</b>.`,
  'jxtn1ux1is': R`Semua elektron berpasangan: <b>diamagnetik</b>.`,
  '6qh8gmpis6': R`Manakah yang ikatan O–O-nya lebih kuat: $\ce{⟦0⟧}$ atau $\ce{⟦1⟧}$?`,
  'fwos4jfwx0': R`Orde ikatan: $\ce{⟦0⟧}$ ⟦1⟧, $\ce{⟦2⟧}$ ⟦3⟧. Orde lebih tinggi, ikatan lebih kuat. (Melepas elektron dari π* menaikkan orde ikatan.)`,
  '1df6oa2fga': R`<p>Mengapa sebagian reaksi berlangsung dengan sendirinya dan yang lain tidak? Energi (entalpi) hanya separuh jawabannya; separuh lainnya adalah <b>entropi</b> $S$, ukuran banyaknya cara partikel dan energinya dapat disusun ("ketidakteraturan"). <b>Hukum kedua termodinamika</b>: dalam proses spontan, entropi total alam semesta bertambah.</p>
⟦0⟧
⟦1⟧
⟦2⟧
⟦3⟧
⟦4⟧`,
  '2000yyzedb3': R`<p>Entropi bertambah: padat → cair → gas; pelarutan; terbentuk lebih banyak molekul gas; suhu lebih tinggi. $$\Delta S^\circ = \sum S^\circ(\text{hasil}) - \sum S^\circ(\text{pereaksi}) \quad (\mathrm{J\,K^{-1}\,mol^{-1}})$$ <b>Energi bebas Gibbs</b> menggabungkan keduanya: $$\Delta G = \Delta H - T\Delta S$$ Reaksi berlangsung spontan jika $\Delta G < 0$.</p>`,
  'l19v55ado2': R`spontan di atas 1106 K`,
  '2918neqhczd': R`spontan di bawah 462 K`,
  '1bqrzxxjhnm': R`Energi Gibbs terhadap suhu untuk penguraian batu kapur, yang menjadi spontan di atas sekitar 1100 kelvin, dan untuk pembuatan amonia, spontan di bawah sekitar 460 kelvin`,
  '17zav8jq39d': R`$\Delta G = \Delta H - T\Delta S$ adalah garis lurus terhadap $T$ dengan kemiringan $-\Delta S$. Batu kapur ($\Delta H = +178$ kJ, $\Delta S = +161$ J/K) hanya terurai di atas $T = \frac{\Delta H}{\Delta S} \approx 1106$ K; sintesis amonia ($\Delta H = -92$ kJ, $\Delta S = -199$ J/K) hanya spontan di bawah sekitar 462 K (nilai dari tabel data standar).`,
  'saastm53ja': R`Spontan?`,
  '5oadgqgn3n': R`selalu −`,
  '1ebb4p9jkqs': R`pada semua suhu`,
  '1f3rkh10vnz': R`selalu +`,
  'iare7lttic': R`tidak pernah`,
  '2bfuwvw8hlu': R`− pada T rendah`,
  'euol23471e': R`pada suhu rendah`,
  '8w6mv50wlr': R`− pada T tinggi`,
  '5is9qqbe2g': R`pada suhu tinggi`,
  '13klqsdbpdz': R`<p>Hubungan dengan kesetimbangan dan elektrokimia: $$\Delta G^\circ = -RT\ln K \qquad \Delta G^\circ = -nFE^\circ_{\text{sel}}$$ dan <b>persamaan Nernst</b> untuk konsentrasi tidak standar: $$E = E^\circ - \frac{RT}{nF}\ln Q \;=\; E^\circ - \frac{0{,}0592}{n}\log Q \ (25\ °\mathrm{C})$$</p>`,
  '27a1rii9lzm': R`<p>"Spontan" tidak menyatakan kecepatan: intan berubah menjadi grafit memiliki $\Delta G < 0$ tetapi sangat-sangat lambat. Termodinamika menjawab <i>apakah</i> terjadi, kinetika menjawab <i>seberapa cepat</i>.</p>`,
  'myn0qbjkl3': R`$\Delta H = ⟦0⟧$ kJ dan $\Delta S = ⟦1⟧$ J/K. Tentukan $\Delta G$ (dalam kJ) pada ⟦2⟧ K.`,
  '10d0ehk2wgb': R`$\Delta G = ⟦0⟧ - ⟦1⟧ \times (⟦2⟧) = ⟦3⟧$ kJ (ubah $\Delta S$ ke kJ/K!).`,
  'khxvmbk2a': R`Suatu reaksi endoterm memiliki $\Delta H = +⟦0⟧$ kJ dan $\Delta S = +⟦1⟧$ J/K. Di atas suhu berapa (dalam K) reaksi ini spontan?`,
  '16mmze4r06l': R`$\Delta G = 0$ pada $T = \frac{\Delta H}{\Delta S} = \frac{⟦0⟧\,000}{⟦1⟧} = ⟦2⟧$ K.`,
  '2bwkycp0x7n': R`air membeku`,
  '1nhk0f9yjap': R`es mencair`,
  'dk578sdpim': R`garam larut dalam air`,
  '17p1umlwoh9': R`uap air mengembun`,
  '1mz0guf5p7f': R`Apakah $\Delta S$ positif atau negatif untuk ⟦0⟧?`,
  'hvzodv5ig1': R`Ketidakteraturan bertambah (gas bertambah, atau padat → cair): <b>positif</b>.`,
  '6smhg2z4oa': R`Ketidakteraturan berkurang: <b>negatif</b>.`,
  'pwyk0jd4f3': R`Pada 298 K, $K = ⟦0⟧$. Berapa $\Delta G^\circ$ (dalam kJ/mol)? ($R = 8{,}314$)`,
  'rrk1v85oay': R`$\Delta G^\circ = -RT\ln K = -8{,}314 \times 298 \times \ln(⟦0⟧) = ⟦1⟧$ kJ/mol.`,
  '76is3ifnwb': R`Suatu reaksi sel memindahkan ⟦0⟧ mol elektron dan memiliki $E^\circ = ⟦1⟧$ V. Berapa $\Delta G^\circ$ (dalam kJ)? ($F = 96\,485$ C/mol)`,
  '29wbxk1hb5l': R`$\Delta G^\circ = -nFE^\circ = -⟦0⟧ \times 96\,485 \times ⟦1⟧ = ⟦2⟧$ kJ.`,
  'kl560cx7ko': R`Suatu sel memiliki $E^\circ = 1{,}10$ V dan $n = ⟦0⟧$. Berapa $E$ (dalam V) jika $Q = ⟦1⟧$ pada 25 °C?`,
  '1pjes8zj8mj': R`$E = 1{,}10 - \frac{0{,}0592}{⟦0⟧}\log ⟦1⟧ = ⟦2⟧$ V.`,
  '8yqcs5631s': R`<p>Tetapan laju sangat bergantung pada suhu. Svante Arrhenius (1889) menemukan:</p>
⟦0⟧
<p>$A$ adalah faktor pra-eksponensial (frekuensi); $e^{-E_a/RT}$ adalah fraksi tumbukan yang energinya cukup. Grafik $\ln k$ terhadap $1/T$ berupa garis lurus dengan gradien $-E_a/R$.</p>
⟦1⟧
⟦2⟧
⟦3⟧
⟦4⟧`,
  'hk2liavumd': R`k = A\,e^{-E_a/RT} \qquad \ln k = \ln A - \frac{E_a}{R}\cdot\frac{1}{T}`,
  '1o0vmzz615b': R`gradien = −Eₐ/R`,
  '96s1tr4ejx': R`Grafik Arrhenius: logaritma natural k terhadap satu per T berupa garis lurus dengan kemiringan negatif`,
  '1us98var9bz': R`Grafik Arrhenius. Di sini gradiennya $-6{,}5 \times 10^{3}$ K, jadi $E_a = 6{,}5 \times 10^3 \times 8{,}314 = 54$ kJ/mol. Bentuk dua suhunya $\ln\frac{k_2}{k_1} = \frac{E_a}{R}\left(\frac{1}{T_1} - \frac{1}{T_2}\right)$.`,
  '1f31f1ut2sr': R`Orde`,
  '2c0hixmib8m': R`Hukum laju terintegrasi`,
  'k3daltx6l2': R`Grafik garis lurus`,
  '1xbpo4y8mw3': R`Waktu paruh`,
  'pdsaijdiqb': R`<p>Kebanyakan reaksi berlangsung melalui serangkaian <b>tahap elementer</b>: <b>mekanisme reaksi</b>. Tahap paling lambat adalah <b>tahap penentu laju</b>; persamaan laju hanya memuat spesi dalam (atau sebelum) tahap itu. Contoh: $\ce{NO2 + CO -> NO + CO2}$ memiliki laju $= k[\ce{NO2}]^2$ karena tahap lambatnya $\ce{2NO2 -> NO3 + NO}$, diikuti tahap cepat $\ce{NO3 + CO -> NO2 + CO2}$. $\ce{NO3}$ adalah <b>zat antara</b>: dibentuk pada satu tahap, dipakai pada tahap berikutnya.</p>`,
  'pgxszwqq84': R`<p>Katalis menyediakan mekanisme lain dengan tahap penentu laju berenergi lebih rendah. Enzim mengikuti kinetika Michaelis–Menten: laju mendatar ketika semua sisi aktif sudah terisi.</p>`,
  '4jtxj54ydq': R`$E_a = ⟦0⟧$ kJ/mol. Berapa kali $k$ naik dari 300 K ke ⟦1⟧ K? ($R = 8{,}314$)`,
  'wzuc9npqvx': R`$\ln\frac{k_2}{k_1} = \frac{⟦0⟧}{8{,}314}\left(\frac{1}{300} - \frac{1}{⟦1⟧}\right) = ⟦2⟧$, jadi $\frac{k_2}{k_1} = ⟦3⟧$.`,
  '2acrhsbyjdr': R`Grafik Arrhenius $\ln k$ terhadap $1/T$ memiliki gradien $⟦0⟧$ K. Berapa $E_a$ (dalam kJ/mol)?`,
  'xgwrujoar4': R`$E_a = -\text{gradien} \times R = ⟦0⟧ \times 8{,}314 = ⟦1⟧$ J/mol $= ⟦2⟧$ kJ/mol.`,
  '1zvlvtsld1e': R`Suatu reaksi orde satu memiliki $k = ⟦0⟧$ menit⁻¹ dan $[A]_0 = ⟦1⟧$ M. Berapa $[A]$ (dalam M) setelah ⟦2⟧ menit?`,
  '1i1jhvtegcu': R`[A] terhadap t`,
  '1oiwikzvr46': R`ln[A] terhadap t`,
  '1c6a16iessp': R`1/[A] terhadap t`,
  'i6izcrck5z': R`Grafik manakah yang berupa garis lurus untuk reaksi berorde ⟦0⟧ terhadap A?`,
  '1kgok4ura6s': R`Tahap 1: 2NO₂ → NO₃ + NO (lambat). Tahap 2: NO₃ + CO → NO₂ + CO₂ (cepat). Bagaimana persamaan lajunya?`,
  '1rsijdhh3qd': R`laju = k[NO₂]²`,
  's1ahu305py': R`laju = k[NO₂][CO]`,
  '2al34lkcm15': R`laju = k[NO₃][CO]`,
  'srlir9idud': R`laju = k[CO]`,
  '7begek3bxx': R`Hanya spesi pada tahap lambat (penentu laju) yang muncul.`,
  '5jdvj0mqk9': R`Dalam mekanisme reaksi, apa itu zat antara?`,
  'zeeip6an19': R`Spesi yang dibentuk pada satu tahap dan habis dipakai pada tahap berikutnya`,
  '29qmzc0qeoo': R`Katalisnya`,
  '1pq8rsx4ohi': R`Tahap paling lambat`,
  '1gt3bs9ees5': R`Hasil akhir`,
  '14h5hh1a6x3': R`Zat antara tidak muncul dalam persamaan reaksi keseluruhan.`,
  '1uc3m4o794w': R`<p>Kimiawan modern mengenali senyawa dari cara senyawa itu berinteraksi dengan energi. Setiap teknik memberi petunjuk yang berbeda.</p>
⟦0⟧
⟦1⟧
⟦2⟧
⟦3⟧
⟦4⟧`,
  '1m2sg2y2o78': R`massa/muatan (m/z)`,
  '12xg9igc187': R`Spektrum massa etanol: ion molekul pada 46 dan puncak dasar pada 31`,
  '1m6uwkh2dzf': R`<b>Spektrum massa</b> etanol (data NIST, disederhanakan). Ion molekul $\ce{M+}$ pada $m/z$ 46 memberikan $M_r$; fragmen menunjukkan potongan-potongannya: 31 adalah $\ce{CH2OH+}$ (puncak tertinggi, puncak dasar), 45 adalah $\ce{M - H}$, 29 adalah $\ce{C2H5+}$.`,
  'swvc1j1rlm': R`bilangan gelombang (cm⁻¹)`,
  '1io0y67s5r5': R`Spektrum inframerah etanol dengan lembah O–H yang lebar dekat 3350, C–H dekat 2970, dan C–O dekat 1050 bilangan gelombang`,
  '1cm23fmb5q5': R`<b>Spektrum inframerah</b> etanol (skematis). Ikatan menyerap IR pada bilangan gelombang yang khas: O–H lebar (alkohol) 3200–3550, C–H 2850–3000, C=O 1680–1750 (tajam, kuat), C–O 1000–1300 cm⁻¹. Di bawah 1500 cm⁻¹ adalah "daerah sidik jari" yang unik.`,
  '1t733hi3xq1': R`geseran kimia δ (ppm)`,
  '1jeaygzykj4': R`Spektrum NMR proton etanol: triplet dekat 1,2, singlet dekat 2,6, dan kuartet dekat 3,7 ppm`,
  '11qjqhgu6if': R`<b>Spektrum ¹H NMR</b> etanol (skematis). Tiga lingkungan menghasilkan tiga sinyal; luasnya berbanding 3 : 1 : 2. Menurut <b>aturan n + 1</b>, $\ce{CH3}$ yang bersebelahan dengan $\ce{CH2}$ terpecah menjadi triplet, $\ce{CH2}$ yang bersebelahan dengan $\ce{CH3}$ menjadi kuartet. Proton OH biasanya muncul sebagai singlet.`,
  'pfyhrl2zpo': R`<p><b>Spektroskopi UV–tampak</b> mengukur banyaknya cahaya yang diserap larutan berwarna. <b>Hukum Lambert–Beer</b>: $$A = \varepsilon\,c\,l$$ absorbans = absorptivitas molar × konsentrasi × panjang lintasan (biasanya 1 cm). Kurva kalibrasi $A$ terhadap $c$ dari larutan-larutan standar memberikan konsentrasi larutan yang tidak diketahui.</p>`,
  '2c08hx3fdtj': R`<p>Ringkasan: MS → massa molar dan fragmen; IR → gugus fungsi; NMR → kerangka karbon–hidrogen; UV–tampak → konsentrasi dan konjugasi. Kristalografi sinar-X memberikan struktur 3-D lengkap.</p>`,
  '133veg1s5yw': R`Di daerah mana (cm⁻¹) ikatan ⟦0⟧ menyerap dalam spektrum IR?`,
  '2bv4l6jj6lt': R`<b>⟦0⟧</b> cm⁻¹.`,
  '23kjl11yhal': R`Sebuah proton memiliki ⟦0⟧ atom H setara pada karbon tetangganya. Menjadi berapa puncak sinyal NMR-nya terpecah?`,
  'e0qqi2sx7k': R`Aturan $n + 1$: ⟦0⟧ + 1 = <b>⟦1⟧</b> (⟦2⟧).`,
  '2cyaogr5nlv': R`Berapa lingkungan ¹H yang berbeda (sinyal NMR) dalam $\ce{⟦0⟧}$?`,
  '2almjtk895x': R`Hitung hidrogen dengan lingkungan yang berbeda: <b>⟦0⟧</b>.`,
  '2amgljnqxyt': R`$\varepsilon = ⟦0⟧$ L mol⁻¹ cm⁻¹, $l = 1$ cm, $c = ⟦1⟧$ M. Berapa absorbansinya?`,
  '1g494ap7z7y': R`Suatu larutan dengan $\varepsilon = ⟦0⟧$ L mol⁻¹ cm⁻¹ dalam kuvet 1 cm memiliki absorbans ⟦1⟧. Berapa konsentrasinya?`,
  '1avkqsayq24': R`Pada $m/z$ berapa puncak ion molekul $\ce{⟦0⟧}$? (H = 1, C = 12, O = 16)`,
  '1rbkwfdghat': R`$M_r = ⟦0⟧$, jadi $\ce{M+}$ pada <b>⟦1⟧</b>.`,
  '1ps9gznjnhx': R`<p>Pada ion logam bebas, kelima orbital $d$ berenergi sama. Dalam kompleks oktahedral, ligan mendekat sepanjang sumbu $x$, $y$, dan $z$ dan menolak dua orbital yang mengarah kepadanya ($d_{x^2-y^2}$, $d_{z^2}$: set $e_g$) lebih kuat daripada tiga orbital yang mengarah di antaranya ($d_{xy}$, $d_{xz}$, $d_{yz}$: $t_{2g}$). Celah energinya disebut <b>pembelahan medan kristal</b> $\Delta_o$.</p>
⟦0⟧
⟦1⟧
⟦2⟧
⟦3⟧`,
  '15fq89ryeh8': R`ion bebas`,
  'pk8b8zv9ex': R`spin tinggi (medan lemah)`,
  '249ftxak6u8': R`d6 spin tinggi: empat elektron tidak berpasangan`,
  '273ggu00607': R`$d^6$ spin tinggi: 4 tidak berpasangan`,
  '1vtyviny9f1': R`spin rendah (medan kuat)`,
  'pxvbmzkfc9': R`d6 spin rendah: keenam elektron berpasangan di tingkat bawah`,
  '4dni6lvkvh': R`$d^6$ spin rendah: 0 tidak berpasangan`,
  'xgzuwgql2c': R`Besi(II), $d^6$. Dengan ligan medan lemah ($\ce{H2O}$) celahnya kecil dan elektron menyebar sebelum berpasangan (spin tinggi, paramagnetik). Dengan ligan medan kuat ($\ce{CN-}$) berpasangan lebih murah daripada melompati celah (spin rendah, diamagnetik): $\ce{[Fe(CN)6]^4-}$.`,
  'f1sbhdj1wd': R`<p><b>Deret spektrokimia</b> (medan lemah → kuat): $$\ce{I- < Br- < Cl- < F- < OH- < H2O < NH3 < en < CN- < CO}$$ $\Delta_o$ yang lebih besar berarti kompleks menyerap cahaya berenergi lebih tinggi (panjang gelombang lebih pendek): $\ce{[Cu(H2O)6]^2+}$ biru muda, $\ce{[Cu(NH3)4(H2O)2]^2+}$ biru keunguan tua. Pada kompleks tetrahedral pembelahannya terbalik dan lebih kecil ($\Delta_t \approx \frac{4}{9}\Delta_o$), sehingga hampir selalu spin tinggi.</p>`,
  '7k3wlwg2aj': R`sebutkan ligan lebih dahulu, menurut abjad, dengan di-, tri-, tetra-, heksa-`,
  'lw2aujaart': R`tetraamina…`,
  'vr9f9aaj6g': R`ligan anion berakhiran -o: klorido, sianido, hidroksido; air = akua, NH₃ = amina`,
  '1rzn4algc7p': R`heksaakua…`,
  '1f8qmyv4x2x': R`lalu logamnya dengan bilangan oksidasi dalam angka Romawi`,
  '14t1jggxh3u': R`heksaakuatembaga(II)`,
  '1853efpvjbr': R`pada kompleks anion, nama logam berakhiran -at`,
  '1yduaplxixz': R`$\ce{[Fe(CN)6]^4-}$: heksasianidoferat(II)`,
  'cwoer3rgqw': R`<p>Kompleks segi empat datar seperti <i>cis</i>-$\ce{[PtCl2(NH3)2]}$ (sisplatin, obat antikanker) menunjukkan isomer cis/trans; kompleks oktahedral dengan ligan bidentat seperti etana-1,2-diamina (en) dapat aktif optis.</p>`,
  '1dmp7ok6ll6': R`Berapa elektron d yang dimiliki ion logam dalam $\ce{⟦0⟧}$?`,
  '1vegj5qyifr': R`Tentukan bilangan oksidasinya, lalu hitung: nomor golongan − muatan = <b>⟦0⟧</b> elektron d.`,
  'g3c2jjofzf': R`Berapa elektron tidak berpasangan pada kompleks oktahedral $d^{⟦1⟧}$ ⟦0⟧?`,
  '1i035a6yzdp': R`spin rendah`,
  'paqkzl89tm': R`spin tinggi`,
  'apng8b3fjt': R`Isi $t_{2g}$ sampai penuh (hingga 6) sebelum $e_g$: <b>⟦0⟧</b> tidak berpasangan.`,
  'edhldwamvu': R`Satu elektron di masing-masing kelima orbital sebelum berpasangan: <b>⟦0⟧</b> tidak berpasangan.`,
  'iwv2qs00xi': R`Manakah ligan medan yang lebih kuat: ⟦0⟧ atau ⟦1⟧?`,
  '2fbgcqyi4cy': R`Lebih kanan dalam deret spektrokimia: <b>⟦0⟧</b>.`,
  'vhzywdnc8': R`ion heksaakuatembaga(II)`,
  'vlllx7lz8d': R`ion heksaaminakobalt(III)`,
  '54jqw27kzs': R`ion heksasianidoferat(III)`,
  '27womtyfz25': R`ion tetrakloridokuprat(II)`,
  'sb60qx54sj': R`ion diaminaperak(I)`,
  '2fa04zct77y': R`Mengapa kompleks tetrahedral hampir selalu spin tinggi?`,
  '2a5d1isxcd7': R`Pembelahannya kecil, sehingga berpasangan lebih mahal daripada melompati celah`,
  '18nox5052zh': R`Tidak memiliki elektron d`,
  'kbxe19rzv5': R`Ligannya selalu medan kuat`,
  'o1hphxomlz': R`Memiliki enam ligan`,
  '2g7fkuwm54c': R`Mengganti ligan H₂O dengan NH₃ menaikkan Δₒ. Bagaimana perubahan cahaya yang diserap?`,
  '16a8gmglpwb': R`Cahaya dengan panjang gelombang lebih pendek (energi lebih tinggi) yang diserap`,
  '1mfo1ky97iu': R`Cahaya dengan panjang gelombang lebih panjang yang diserap`,
  '29co2s3n6hd': R`Tidak ada cahaya yang diserap`,
  '2fkrilhqdmt': R`Celah lebih besar, foton berenergi lebih tinggi.`,
});
